//! Exact Habery vectors generated by the pinned TypeScript reference.
//!
//! `makeHab` hardcodes the production Argon2 profile, so every event here re-derives its keys at a
//! real 64 MiB per key — which is exactly why they are worth pinning: they are the events a
//! deployed client actually produces. A named salty registry holds one habitat per
//! transferability, so each case builds a fresh registry, as the generator did.

use std::error::Error;

use keri_cesr::crypto::salt::{Salt, SecurityTier};
use keri_cesr::crypto::verifier::KeyTransferability;
use serde::Deserialize;
use signify_keri::event::ConfigurationTrait;
use signify_keri::identifier::{Habery, Habitat, HabitatRequest, IdentifierError};
use signify_keri::manager::ManagerError;
use signify_keri::prefix::IdentifierPrefix;
use signify_keri::serialization::{Sad, SadValue};
use signify_keri::threshold::SigningThreshold;

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";
const FIXTURE: &str = include_str!("../../../fixtures/keri-habery/v1.json");

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    provenance: Provenance,
    pinned_unit_tests: PinnedUnitTests,
    habitat_cases: Vec<HabitatCase>,
    pidx_does_not_change_a_named_habitat: PidxCase,
    mixed_transferability: MixedTransferability,
    rejections: Vec<Rejection>,
    reference_quirks: Quirks,
}

#[derive(Debug, Deserialize)]
struct Provenance {
    salt_raw: String,
    salt_qb64: String,
    passcode: String,
    delegator: String,
    witnesses: Vec<String>,
    note: String,
}

#[derive(Debug, Deserialize)]
struct PinnedUnitTests {
    salt_and_passcode: SaltAndPasscode,
    passcode_as_salt: PasscodeAsSalt,
}

#[derive(Debug, Deserialize)]
struct SaltAndPasscode {
    aeid: String,
    event: EventRecord,
}

#[derive(Debug, Deserialize)]
struct PasscodeAsSalt {
    bran: String,
    signer_qb64: String,
    signer_verfer: String,
    event: EventRecord,
}

#[derive(Debug, Deserialize)]
struct EventRecord {
    habitat_name: String,
    raw: String,
    pre: String,
    said: String,
    keys: Vec<String>,
    next_digests: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct HabitatCase {
    name: String,
    habery_name: String,
    args: CaseArgs,
    event: EventRecord,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct CaseArgs {
    icount: Option<usize>,
    ncount: Option<usize>,
    isith: Option<String>,
    nsith: Option<String>,
    transferable: Option<bool>,
    wits: Option<Vec<String>>,
    toad: Option<u32>,
    #[serde(rename = "estOnly")]
    est_only: Option<bool>,
    #[serde(rename = "DnD")]
    dnd: Option<bool>,
    data: Option<Vec<serde_json::Map<String, serde_json::Value>>>,
    delpre: Option<String>,
}

#[derive(Debug, Deserialize)]
struct PidxCase {
    pidx: u32,
    raw_matches_default: bool,
    note: String,
}

#[derive(Debug, Deserialize)]
struct MixedTransferability {
    controller: EventRecord,
    witness: EventRecord,
    note: String,
}

#[derive(Debug, Deserialize)]
struct Rejection {
    name: String,
    note: String,
    reference_error_message: String,
}

#[derive(Debug, Deserialize)]
struct Quirks {
    tier_argument_is_never_read: TierQuirk,
    passcode_is_ignored_when_a_seed_is_given: PasscodeQuirk,
    duplicate_name_overwrites_the_map_entry: DuplicateQuirk,
    zero_next_keys_get_an_unsatisfiable_threshold: UnsatisfiableQuirk,
    randy_habitats_are_unreachable: RandyQuirk,
}

#[derive(Debug, Deserialize)]
struct TierQuirk {
    tier_with_argument: String,
    tier_without_argument: String,
    identical: bool,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct PasscodeQuirk {
    accepted_with_one_character_passcode: bool,
    aeid: Option<String>,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct DuplicateQuirk {
    habs_length: usize,
    identifiers_differ: bool,
    pidx_after: u32,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct UnsatisfiableQuirk {
    raw: String,
    nt: String,
    next_digests: Vec<String>,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct RandyQuirk {
    name: String,
    note: String,
    reference_error_message: String,
    rust_decision: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(FIXTURE)?)
}

fn salt(fixture: &Fixture) -> Result<Salt, Box<dyn Error>> {
    Ok(Salt::from_raw(
        fixture.provenance.salt_raw.as_bytes(),
        SecurityTier::Low,
    )?)
}

/// Builds the request one fixture case's `MakeHabArgs` describe.
fn request_from_args(args: &CaseArgs) -> Result<HabitatRequest, Box<dyn Error>> {
    let mut request = HabitatRequest::default();
    if let Some(icount) = args.icount {
        request.current_keys = icount;
    }
    request.next_keys = args.ncount;
    if let Some(isith) = &args.isith {
        request.signing_threshold = Some(SigningThreshold::from_sith(isith)?);
    }
    if let Some(nsith) = &args.nsith {
        request.next_threshold = Some(SigningThreshold::from_sith(nsith)?);
    }
    if args.transferable == Some(false) {
        request.transferability = KeyTransferability::NonTransferable;
    }
    if let Some(wits) = &args.wits {
        request.witnesses = wits
            .iter()
            .map(|wit| IdentifierPrefix::from_qb64(wit))
            .collect::<Result<Vec<_>, _>>()?;
    }
    request.witness_threshold = args.toad;
    if args.est_only == Some(true) {
        request.configuration.push(ConfigurationTrait::EstablishmentOnly);
    }
    if args.dnd == Some(true) {
        request.configuration.push(ConfigurationTrait::DoNotDelegate);
    }
    if let Some(data) = &args.data {
        request.anchors = data
            .iter()
            .map(|entry| sad_from_object(entry))
            .collect::<Result<_, _>>()?;
    }
    if let Some(delpre) = &args.delpre {
        request.delegator = Some(IdentifierPrefix::from_qb64(delpre)?);
    }
    Ok(request)
}

/// Builds a seal from a fixture JSON object; the cases here anchor text fields only.
fn sad_from_object(entry: &serde_json::Map<String, serde_json::Value>) -> Result<Sad, Box<dyn Error>> {
    let mut sad = Sad::new();
    for (label, value) in entry {
        match value {
            serde_json::Value::String(text) => sad.insert(label.clone(), SadValue::text(text))?,
            other => return Err(format!("anchor field {label:?} is not text: {other:?}").into()),
        }
    }
    Ok(sad)
}

/// Compares one Rust habitat with the reference's recorded event, byte for byte.
fn assert_event_matches(habitat: &Habitat, expected: &EventRecord) -> Result<(), Box<dyn Error>> {
    assert_eq!(habitat.name(), expected.habitat_name);
    assert_eq!(habitat.inception().raw(), expected.raw.as_bytes());
    assert_eq!(habitat.prefix().qb64()?, expected.pre);
    assert_eq!(habitat.inception().said().qb64()?, expected.said);
    assert_eq!(habitat.inception().sad().get_text("d"), Some(expected.said.as_str()));
    let keys = match habitat.inception().sad().get("k") {
        Some(SadValue::Array(items)) => items
            .iter()
            .filter_map(|item| match item {
                SadValue::Text(text) => Some(text.clone()),
                _ => None,
            })
            .collect::<Vec<_>>(),
        _ => Vec::new(),
    };
    assert_eq!(keys, expected.keys);
    let digests = match habitat.inception().sad().get("n") {
        Some(SadValue::Array(items)) => items
            .iter()
            .filter_map(|item| match item {
                SadValue::Text(text) => Some(text.clone()),
                _ => None,
            })
            .collect::<Vec<_>>(),
        _ => Vec::new(),
    };
    assert_eq!(digests, expected.next_digests);
    Ok(())
}

#[test]
fn the_manifest_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert!(fixture.upstream.contains("WebOfTrust/signify-ts"));
    assert!(!fixture.generated_on.is_empty());
    assert!(fixture.sources.iter().any(|source| source.ends_with("habery.ts")));
    assert!(!fixture.provenance.note.is_empty());
    assert_eq!(fixture.provenance.witnesses.len(), 3);
    // The generator derives its salt from the recorded raw bytes; both spellings must agree.
    assert_eq!(salt(&fixture)?.expose_qb64()?.as_str(), fixture.provenance.salt_qb64);
    Ok(())
}

#[test]
fn the_pinned_salt_and_passcode_case_matches() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let expected = &fixture.pinned_unit_tests.salt_and_passcode;

    let mut habery = Habery::builder("signify")
        .salt(salt(&fixture)?)
        .build_with_passcode(&fixture.provenance.passcode)?;
    assert_eq!(habery.manager().encryption_identifier(), Some(expected.aeid.as_str()));

    let habitat = habery.make_habitat(expected.event.habitat_name.clone(), HabitatRequest::default())?;
    assert_event_matches(habitat, &expected.event)
}

#[test]
fn the_pinned_passcode_as_salt_case_matches() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let expected = &fixture.pinned_unit_tests.passcode_as_salt;

    // The bran is the salt code, one pad character, and the passcode's first 21 characters.
    assert_eq!(expected.bran, format!("0AA{}", &fixture.provenance.passcode[..21]));
    let bran_salt = Salt::from_qb64(&expected.bran, SecurityTier::Low)?;

    // The reference derives its example signer transferable; the Rust signer exposes no seed, so
    // the pinned seed `signer_qb64` is verified through the public key it derives.
    assert!(expected.signer_qb64.starts_with('A'));
    let signer = bran_salt.derive_signer("", KeyTransferability::Transferable)?;
    assert_eq!(signer.verifier().qb64()?, expected.signer_verfer);

    let mut habery = Habery::builder("test").salt(bran_salt).build()?;
    let habitat = habery.make_habitat(expected.event.habitat_name.clone(), HabitatRequest::default())?;
    assert_event_matches(habitat, &expected.event)
}

/// Reproduces one fixture case at the reference's own production Argon2 cost.
///
/// The cases are separate tests so they re-derive their keys in parallel; together they cover the
/// whole `MakeHabArgs` space the reference can reach.
fn assert_habitat_case(name: &str) -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.habitat_cases.len(), 13);
    let case = fixture
        .habitat_cases
        .iter()
        .find(|case| case.name == name)
        .ok_or_else(|| format!("the fixture has no case named {name:?}"))?;
    let mut habery = Habery::builder(case.habery_name.clone())
        .salt(salt(&fixture)?)
        .build()?;
    let request = request_from_args(&case.args)?;
    let habitat = habery.make_habitat(case.event.habitat_name.clone(), request)?;
    assert_event_matches(habitat, &case.event).map_err(|error| format!("case {}: {error}", case.name).into())
}

macro_rules! habitat_case_tests {
    ($($test_name:ident => $case:literal,)*) => {
        $(
            #[test]
            fn $test_name() -> Result<(), Box<dyn Error>> {
                assert_habitat_case($case)
            }
        )*
    };
}

habitat_case_tests! {
    habitat_case_default => "default",
    habitat_case_non_transferable => "non_transferable",
    habitat_case_three_keys => "three_keys",
    habitat_case_three_keys_two_next => "three_keys_two_next",
    habitat_case_five_keys => "five_keys",
    habitat_case_explicit_thresholds => "explicit_thresholds",
    habitat_case_isith_propagates_to_nsith => "isith_propagates_to_nsith",
    habitat_case_witnessed_with_toad => "witnessed_with_toad",
    habitat_case_witnessed_default_toad => "witnessed_default_toad",
    habitat_case_configured_with_data => "configured_with_data",
    habitat_case_delegated => "delegated",
    habitat_case_empty_habery_name => "empty_habery_name",
    habitat_case_another_stem => "another_stem",
}

#[test]
fn the_prefix_index_does_not_reach_a_named_habitat() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert!(fixture.pidx_does_not_change_a_named_habitat.raw_matches_default);
    assert!(!fixture.pidx_does_not_change_a_named_habitat.note.is_empty());

    let default_case = fixture
        .habitat_cases
        .iter()
        .find(|case| case.name == "default")
        .ok_or("the fixture has no default case")?;
    let mut habery = Habery::builder("signify")
        .salt(salt(&fixture)?)
        .prefix_index(fixture.pidx_does_not_change_a_named_habitat.pidx)
        .build()?;
    let habitat = habery.make_habitat("test", HabitatRequest::default())?;
    assert_eq!(habitat.inception().raw(), default_case.event.raw.as_bytes());
    Ok(())
}

#[test]
fn one_registry_holds_both_transferabilities() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let expected = &fixture.mixed_transferability;
    assert!(!expected.note.is_empty());

    let mut habery = Habery::builder("signify").salt(salt(&fixture)?).build()?;
    let controller = habery
        .make_habitat(expected.controller.habitat_name.clone(), HabitatRequest::default())?
        .clone();
    assert_event_matches(&controller, &expected.controller)?;
    let witness = habery.make_habitat(
        expected.witness.habitat_name.clone(),
        HabitatRequest {
            transferability: KeyTransferability::NonTransferable,
            ..HabitatRequest::default()
        },
    )?;
    assert_event_matches(witness, &expected.witness)
}

#[test]
fn every_reference_rejection_is_refused_here_too() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.rejections.len(), 8);
    let salt_qb64 = fixture.provenance.salt_qb64.clone();
    let fresh = || -> Result<Habery, Box<dyn Error>> {
        Ok(Habery::builder("signify")
            .salt(Salt::from_qb64(&salt_qb64, SecurityTier::Low)?)
            .build()?)
    };
    let witness = IdentifierPrefix::from_qb64(
        fixture
            .provenance
            .witnesses
            .first()
            .ok_or("the fixture records no witnesses")?,
    )?;
    let delegator = IdentifierPrefix::from_qb64(&fixture.provenance.delegator)?;

    for rejection in &fixture.rejections {
        assert!(!rejection.reference_error_message.is_empty(), "{}", rejection.name);
        assert!(!rejection.note.is_empty(), "{}", rejection.name);
        let outcome: Result<(), IdentifierError> = match rejection.name.as_str() {
            "passcode_too_short" => Habery::builder("signify")
                .build_with_passcode(&fixture.provenance.passcode[..20])
                .map(|_| ()),
            "second_salty_habitat" => {
                let mut habery = fresh()?;
                habery.make_habitat("first", HabitatRequest::default())?;
                habery.make_habitat("second", HabitatRequest::default()).map(|_| ())
            }
            "no_current_keys" => fresh()?
                .make_habitat(
                    "test",
                    HabitatRequest {
                        current_keys: 0,
                        ..HabitatRequest::default()
                    },
                )
                .map(|_| ()),
            "randy_without_encryption" => Habery::builder("signify").build().map(|_| ()),
            "toad_above_witness_count" => fresh()?
                .make_habitat(
                    "test",
                    HabitatRequest {
                        witnesses: vec![witness.clone()],
                        witness_threshold: Some(2),
                        ..HabitatRequest::default()
                    },
                )
                .map(|_| ()),
            "duplicate_witnesses" => fresh()?
                .make_habitat(
                    "test",
                    HabitatRequest {
                        witnesses: vec![witness.clone(), witness.clone()],
                        ..HabitatRequest::default()
                    },
                )
                .map(|_| ()),
            "non_transferable_with_witnesses" => fresh()?
                .make_habitat(
                    "test",
                    HabitatRequest {
                        transferability: KeyTransferability::NonTransferable,
                        witnesses: vec![witness.clone()],
                        ..HabitatRequest::default()
                    },
                )
                .map(|_| ()),
            "non_transferable_delegated" => fresh()?
                .make_habitat(
                    "test",
                    HabitatRequest {
                        transferability: KeyTransferability::NonTransferable,
                        delegator: Some(delegator.clone()),
                        ..HabitatRequest::default()
                    },
                )
                .map(|_| ()),
            other => return Err(format!("unknown rejection case {other:?}").into()),
        };
        assert!(outcome.is_err(), "{} was accepted", rejection.name);
    }

    // The one rejection whose Rust variant is worth pinning by name: the reference throws
    // `Already incepted pre=…`, and the Rust manager refuses identically.
    let mut habery = fresh()?;
    habery.make_habitat("first", HabitatRequest::default())?;
    assert!(matches!(
        habery.make_habitat("second", HabitatRequest::default()),
        Err(IdentifierError::Manager { source }) if matches!(*source, ManagerError::AlreadyIncepted { .. })
    ));
    Ok(())
}

#[test]
fn the_reference_quirks_hold_and_the_divergences_are_deliberate() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // The unread tier argument: nothing to run in Rust, because the argument does not exist.
    assert!(quirks.tier_argument_is_never_read.identical);
    assert_eq!(
        quirks.tier_argument_is_never_read.tier_with_argument,
        quirks.tier_argument_is_never_read.tier_without_argument
    );
    assert!(!quirks.tier_argument_is_never_read.note.is_empty());
    assert!(!quirks.tier_argument_is_never_read.rust_decision.is_empty());

    // The ignored passcode: the reference accepted a one-character passcode beside a seed and
    // derived no encryption identifier from it. The Rust builder cannot express the combination.
    assert!(
        quirks
            .passcode_is_ignored_when_a_seed_is_given
            .accepted_with_one_character_passcode
    );
    assert_eq!(quirks.passcode_is_ignored_when_a_seed_is_given.aeid, None);
    assert!(!quirks.passcode_is_ignored_when_a_seed_is_given.note.is_empty());
    assert!(!quirks.passcode_is_ignored_when_a_seed_is_given.rust_decision.is_empty());

    // The duplicate-name overwrite: one map entry, two identifiers. Rust refuses instead, through
    // the only registry shape that can reach a second same-transferability habitat.
    assert_eq!(quirks.duplicate_name_overwrites_the_map_entry.habs_length, 1);
    assert!(quirks.duplicate_name_overwrites_the_map_entry.identifiers_differ);
    assert_eq!(quirks.duplicate_name_overwrites_the_map_entry.pidx_after, 2);
    assert!(!quirks.duplicate_name_overwrites_the_map_entry.note.is_empty());
    assert!(!quirks.duplicate_name_overwrites_the_map_entry.rust_decision.is_empty());
    let mut unnamed = Habery::builder("").salt(salt(&fixture)?).build()?;
    unnamed.make_habitat("same", HabitatRequest::default())?;
    assert!(matches!(
        unnamed.make_habitat("same", HabitatRequest::default()),
        Err(IdentifierError::DuplicateHabitat { .. })
    ));

    // The unsatisfiable next threshold: the reference's event carries a threshold of one over an
    // empty next-key list. Rust refuses the same input.
    assert_eq!(quirks.zero_next_keys_get_an_unsatisfiable_threshold.nt, "1");
    assert!(
        quirks
            .zero_next_keys_get_an_unsatisfiable_threshold
            .next_digests
            .is_empty()
    );
    assert!(!quirks.zero_next_keys_get_an_unsatisfiable_threshold.note.is_empty());
    assert!(
        !quirks
            .zero_next_keys_get_an_unsatisfiable_threshold
            .rust_decision
            .is_empty()
    );
    assert!(
        quirks
            .zero_next_keys_get_an_unsatisfiable_threshold
            .raw
            .contains("\"nt\":\"1\",\"n\":[]")
    );
    let mut habery = Habery::builder("signify").salt(salt(&fixture)?).build()?;
    assert!(matches!(
        habery.make_habitat(
            "test",
            HabitatRequest {
                next_keys: Some(0),
                ..HabitatRequest::default()
            },
        ),
        Err(IdentifierError::Event { .. })
    ));

    // Unreachable randy habitats: the reference throws `Empty Material` reading a salt the randy
    // algorithm never uses. Rust reads a salt only for the salty algorithm, so the registry works;
    // its shape is asserted here, since the reference cannot emit one to pin.
    assert_eq!(
        quirks.randy_habitats_are_unreachable.reference_error_message,
        "Empty Material"
    );
    assert_eq!(quirks.randy_habitats_are_unreachable.name, "randy_habitat");
    assert!(!quirks.randy_habitats_are_unreachable.note.is_empty());
    assert!(!quirks.randy_habitats_are_unreachable.rust_decision.is_empty());
    let mut randy = Habery::builder("signify").build_with_passcode(&fixture.provenance.passcode)?;
    let habitat = randy.make_habitat("one", HabitatRequest::default())?;
    let keys = &habitat.inception().sad().get("k").cloned();
    assert!(matches!(keys, Some(SadValue::Array(items)) if items.len() == 1));
    assert!(habitat.prefix().qb64()?.starts_with('E'));
    assert_eq!(habitat.inception().sad().get_text("kt"), Some("1"));
    assert_eq!(habitat.inception().sad().get_text("nt"), Some("1"));
    Ok(())
}
